sys_security_acl.script:
answer = false;

if(current.employee.manager == gs.getUserID()){
	answer = true;
} 
else if(gs.hasRole('x_1921751_employ_0.approver')){
	answer = true;
}
else if(current.current_approver == gs.getUserID()){
	answer = true;
}
else if(current.status == 'draft' && (current.requested_by == gs.getUserID() || gs.hasRole('x_1921751_employ_0.admin'))){
	answer = true;
}

